def get_imports_for_annotation(anno: Any) -> ImportMap:
    imports = ImportMap()
    if anno is inspect.Parameter.empty or anno is inspect.Signature.empty:
        return imports
    if is_forward_ref(anno):
        return imports
    if is_union(anno):
        for arg in anno.__args__:
            imports.merge(get_imports_for_annotation(arg))
        if _is_optional(anno):
            imports["typing"].add("Optional")
        else:
            imports["typing"].add("Union")
        return imports
    if is_generic(anno):
        qualname = qualname_of_generic(anno)
        if qualname is not None:
            module = _get_import_for_qualname(qualname)
            if module == "typing":
                name = qualname.split(".")[-1]
                imports["typing"].add(name)
        args = getattr(anno, "__args__", None)
        if args:
            for arg in args:
                if arg == ():
                    continue
                imports.merge(get_imports_for_annotation(arg))
        return imports
    if is_any(anno):
        imports["typing"].add("Any")
        return imports
    if anno is NoneType or isinstance(anno, NoneType):
        return imports
    if anno is None:
        return imports
    if isinstance(anno, type):
        if hasattr(anno, "__supertype__"):
            return imports
        if anno.__module__ == "builtins":
            return imports
        # Check for nested class
        qualname = anno.__qualname__
        top_level_name = qualname.split(".")[0]
        imports[anno.__module__].add(top_level_name)
        return imports
    if isinstance(anno, str):
        return imports
    return imports
