def update_signature_args(sig: inspect.Signature, arg_types: Dict[str, type], has_self: bool, existing_annotation_strategy: ExistingAnnotationStrategy = ExistingAnnotationStrategy.REPLICATE) -> inspect.Signature:
    params = list(sig.parameters.values())
    new_params = []
    for i, param in enumerate(params):
        if has_self and i == 0:
            new_params.append(param.replace(annotation=inspect.Parameter.empty))
            continue
        typ = arg_types.get(param.name)
        if typ is None:
            new_params.append(param)
            continue
        has_existing = param.annotation is not inspect.Parameter.empty
        if existing_annotation_strategy == ExistingAnnotationStrategy.REPLICATE:
            if has_existing:
                new_params.append(param)
            else:
                new_params.append(param.replace(annotation=typ))
        elif existing_annotation_strategy == ExistingAnnotationStrategy.IGNORE:
            if typ is None or typ == type(None) and not isinstance(typ, type):
                new_params.append(param.replace(annotation=inspect.Parameter.empty))
            else:
                new_params.append(param.replace(annotation=typ))
        elif existing_annotation_strategy == ExistingAnnotationStrategy.OMIT:
            if has_existing:
                new_params.append(param.replace(annotation=inspect.Parameter.empty))
            else:
                new_params.append(param.replace(annotation=typ))
    return sig.replace(parameters=new_params)
