def update_signature_return(sig: inspect.Signature, return_type: Optional[type] = None, yield_type: Optional[type] = None, existing_annotation_strategy: ExistingAnnotationStrategy = ExistingAnnotationStrategy.REPLICATE) -> inspect.Signature:
    has_existing = sig.return_annotation is not inspect.Signature.empty
    if yield_type is not None:
        if return_type is None or return_type is NoneType:
            new_return = make_iterator(yield_type)
        else:
            new_return = make_generator(yield_type, NoneType, return_type)
        return sig.replace(return_annotation=new_return)
    if return_type is None:
        return sig
    if existing_annotation_strategy == ExistingAnnotationStrategy.REPLICATE:
        if has_existing:
            return sig
        return sig.replace(return_annotation=return_type)
    elif existing_annotation_strategy == ExistingAnnotationStrategy.IGNORE:
        return sig.replace(return_annotation=return_type)
    elif existing_annotation_strategy == ExistingAnnotationStrategy.OMIT:
        if has_existing:
            return sig.replace(return_annotation=inspect.Signature.empty)
        return sig.replace(return_annotation=return_type)
    return sig
