def render_signature(sig: inspect.Signature, max_line_len: Optional[int] = None, prefix: str = '') -> str:
    params = list(sig.parameters.values())
    rendered_params = [render_parameter(p) for p in params]
    if sig.return_annotation is inspect.Signature.empty:
        return_str = ""
    else:
        return_str = " -> " + render_annotation(sig.return_annotation)
    single_line = "(" + ", ".join(rendered_params) + ")" + return_str
    if max_line_len is None or len(single_line) <= max_line_len:
        return single_line
    indent = prefix + "    "
    lines = ["("]
    for i, p in enumerate(rendered_params):
        if i < len(rendered_params) - 1:
            lines.append(f"{indent}{p},")
        else:
            lines.append(f"{indent}{p}")
    lines.append(f"{prefix}){return_str}")
    return "\n".join(lines)
