def build_module_stubs(entries: Iterable[FunctionDefinition]) -> Dict[str, ModuleStub]:
    module_stubs: Dict[str, ModuleStub] = {}
    module_function_stubs: DefaultDict[str, Dict[str, FunctionStub]] = collections.defaultdict(dict)
    module_class_stubs: DefaultDict[str, Dict[str, ClassStub]] = collections.defaultdict(dict)
    module_imports: DefaultDict[str, ImportMap] = collections.defaultdict(ImportMap)
    module_typed_dict_stubs: DefaultDict[str, List[ClassStub]] = collections.defaultdict(list)

    for entry in entries:
        module = entry.module
        qualname = entry.qualname
        parts = qualname.split(".")
        to_strip = ["typing"]
        func_stub = FunctionStub(
            parts[-1],
            entry.signature,
            entry.kind,
            to_strip,
            entry.is_async,
        )
        imports = get_imports_for_signature(entry.signature)
        module_imports[module].merge(imports)

        if entry.typed_dict_class_stubs:
            module_typed_dict_stubs[module].extend(entry.typed_dict_class_stubs)
            module_imports[module]["mypy_extensions"].add("TypedDict")

        if len(parts) == 1:
            module_function_stubs[module][parts[0]] = func_stub
        else:
            class_name = parts[0]
            if class_name not in module_class_stubs[module]:
                module_class_stubs[module][class_name] = ClassStub(class_name)
            module_class_stubs[module][class_name].function_stubs[parts[-1]] = func_stub

    all_modules = set(module_function_stubs.keys()) | set(module_class_stubs.keys())
    for module in all_modules:
        imports = module_imports[module]
        # Remove the module itself from imports
        if module in imports:
            del imports[module]
        imports_stub = ImportBlockStub(imports) if imports else ImportBlockStub()
        function_stubs = list(module_function_stubs[module].values())
        class_stubs = list(module_class_stubs[module].values())
        typed_dict_stubs = module_typed_dict_stubs[module]
        module_stubs[module] = ModuleStub(
            function_stubs=function_stubs if function_stubs else None,
            class_stubs=class_stubs if class_stubs else None,
            imports_stub=imports_stub,
            typed_dict_class_stubs=typed_dict_stubs if typed_dict_stubs else None,
        )
    return module_stubs
